@extends('layouts.app')@section('content')<div class="page-head"><div><div class="eyebrow">LEDGER</div><h1>Transactions</h1><p>Financially relevant events recorded once per successful payment.</p></div></div><div class="panel"><form class="toolbar"><input name="q" value="{{ request('q') }}" placeholder="Reference or gateway transaction ID"><select name="type"><option value="">All types</option>@foreach(['payment','refund','adjustment','fee','credit','debit'] as $t)<option value="{{ $t }}" @selected(request('type')===$t)>{{ ucfirst($t) }}</option>@endforeach</select><button class="btn secondary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Business</th><th>Type</th><th>Amount</th><th>Gateway</th><th>Status</th><th>Created</th></tr></thead><tbody>@foreach($transactions as $t)<tr><td class="mono">{{ $t->reference }}</td><td>{{ $t->business->name }}</td><td><span class="badge neutral">{{ ucfirst($t->transaction_type->value) }}</span></td><td>₹{{ number_format($t->net_amount,2) }}</td><td>{{ strtoupper($t->gateway ?: '—') }}</td><td><span class="badge {{ $t->status==='successful'?'success':'neutral' }}">{{ ucfirst($t->status) }}</span></td><td>{{ $t->created_at->format('d M Y H:i') }}</td></tr>@endforeach</tbody></table></div><div class="pagination">{{ $transactions->links() }}</div></div>@endsection
